// Monolith: order place karna = ek process, ek transaction
async function placeOrder(userId, items) {
  return db.transaction(async (tx) => {
    const order = await orders.create(tx, userId, items);
    await inventory.reserve(tx, items);
    await payments.charge(tx, order);   // function call, network nahi
    return order;
  });
}

